'use strict';
const tools=[['records','▤','Registros e planilhas','Registre uma vez. A planilha acompanha.'],['services','↗','Serviços e etapas','Saiba o que falta, quem faz e quando entrega.'],['checks','☑','Conferências e inspeções','Confira cada item e registre pendências.'],['schedule','▦','Agendamentos e retornos','Mantenha os próximos compromissos à vista.'],['reports','▥','Indicadores e relatórios','Transforme registros em decisões.'],['assistant','✧','Assistente de atendimento','Experimente respostas para diferentes pedidos.'],['extract','▧','Extração de informações','Transforme um texto em campos organizados.'],['diagnosis','⌘','Diagnóstico de processos','Descreva uma dificuldade. Explore uma solução.']];
const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem('horizon-preview-v1'))}catch{};state=Object.assign({selected:[],records:[{name:'Conferência de materiais',qty:12,person:'Ana'},{name:'Recebimento de peças',qty:8,person:'Bruno'}],services:[{name:'Revisão de equipamento',person:'Ana',stage:0},{name:'Instalação na unidade 02',person:'Bruno',stage:1},{name:'Manutenção preventiva',person:'Carla',stage:2}],appointments:[],checks:[false,false,false,false],chat:[],turn:0},state||{});const stages=['Recebido','Em execução','Conferência','Concluído'];
function save(){try{localStorage.setItem('horizon-preview-v1',JSON.stringify(state))}catch{toast('O navegador não permitiu salvar. A experiência continua nesta sessão.')}$('#count').textContent=state.selected.length}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',2800)}
function closeMenu(){document.body.classList.remove('menuopen');$('#menu').setAttribute('aria-expanded','false')}
$('#menu').onclick=()=>{document.body.classList.toggle('menuopen');$('#menu').setAttribute('aria-expanded',document.body.classList.contains('menuopen'))};$('#overlay').onclick=closeMenu;document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu()});$('#selection').onclick=()=>location.hash='solucao';
function selected(id){return state.selected.includes(id)}function toggle(id){state.selected=selected(id)?state.selected.filter(x=>x!==id):[...state.selected,id];save();render();toast(selected(id)?'Ferramenta adicionada à sua solução':'Ferramenta removida')}
function addbutton(id){return `<button class="secondary" data-toggle="${id}">${selected(id)?'✓ Na minha solução':'+ Adicionar à solução'}</button>`}
function head(id){const t=tools.find(t=>t[0]===id);return `<div class="demohead"><div><span class="eyebrow">EXPERIMENTE A FERRAMENTA</span><h1>${t[2]}</h1><p>${t[3]}</p></div>${addbutton(id)}</div><div class="notice">Dados fictícios para experimentar. Seus testes ficam apenas neste navegador.${['assistant','diagnosis','extract'].includes(id)?' IA simulada localmente, sem conexão com modelos externos.':''}</div>`}
function home(){return `<section class="hero"><div><span class="eyebrow">TECNOLOGIA QUE SE ENCAIXA NA SUA EMPRESA</span><h1>Sua empresa.<br><em>Seu sistema.</em></h1><p>Escolha as ferramentas que precisa.<br>Nós conectamos e personalizamos tudo para você.</p><div class="actions"><button data-go="records">Experimentar ferramentas →</button><button class="secondary" data-go="diagnosis">Encontrar minha solução</button></div><p class="hint">Sem cadastro. Explore no seu ritmo.</p></div><div class="diagram" aria-label="Ferramentas combinadas em um sistema personalizado"><div class="chip">▤ Registros<span>Uma informação, um só lugar</span></div><div class="chip">↗ Serviços<span>Etapas e responsáveis</span></div><div class="chip">☑ Conferências<span>Mais controle na rotina</span></div><div class="chip">▥ Indicadores<span>Clareza para decidir</span></div><div class="chip">HORIZON · SEU SISTEMA<span>Conectado à forma como você trabalha</span></div></div></section><div class="sectionhead"><div><span class="eyebrow">MONTE SUAS POSSIBILIDADES</span><h2>O que sua empresa precisa?</h2><p>Experimente cada ferramenta e adicione as que fazem sentido.</p></div><input id="search" class="search" placeholder="Buscar ferramenta" aria-label="Buscar ferramenta"></div><section class="grid" id="catalog">${cards(tools)}</section><div class="band"><div><span class="eyebrow">SUA NECESSIDADE VEM PRIMEIRO</span><h3>Não encontrou o que procura?</h3><p>Conte como sua empresa trabalha. A ferramenta pode começar pela sua ideia.</p></div><button data-go="personalizada">Criar ferramenta personalizada →</button></div>`}
function cards(list){return list.map(t=>`<article class="card"><div style="display:flex;justify-content:space-between;align-items:center"><div class="glyph">${t[1]}</div>${['assistant','extract','diagnosis'].includes(t[0])?'<span class="tag">IA · SIMULAÇÃO</span>':'<span class="tag">INTERATIVO</span>'}</div><h3>${t[2]}</h3><p>${t[3]}</p><div class="actions"><button class="textbtn" data-go="${t[0]}">Experimentar →</button><button class="add" data-toggle="${t[0]}" aria-label="${selected(t[0])?'Remover':'Adicionar'} ${t[2]}">${selected(t[0])?'✓ Escolhida':'+ Escolher'}</button></div></article>`).join('')||'<p>Nenhuma ferramenta corresponde à busca.</p>'}
function records(){return `${head('records')}<div class="workspace"><form id="recordform" class="panel"><div class="step">01 / REGISTRE UMA INFORMAÇÃO</div><h3>Um novo registro</h3><label for="rname">Atividade ou material</label><input id="rname" name="name" required maxlength="100" placeholder="Ex.: Recebimento de caixas"><label for="rqty">Quantidade</label><input id="rqty" name="qty" type="number" min="1" max="99999" required value="1"><label for="rperson">Responsável</label><input id="rperson" name="person" required maxlength="60" placeholder="Seu nome"><button class="full">Registrar e atualizar planilha</button></form><section class="panel soft"><div class="step">02 / A PLANILHA ACOMPANHA</div><h3>Registros da operação</h3><p class="hint">Atualização local instantânea nesta demonstração.</p><div class="scroll"><table><thead><tr><th>Atividade</th><th>Qtd.</th><th>Responsável</th></tr></thead><tbody>${state.records.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.qty}</td><td>${esc(r.person)}</td></tr>`).join('')}</tbody></table></div><div class="actions"><button id="csv" class="secondary">Baixar planilha CSV ↓</button><button data-go="reports" class="textbtn">Ver indicadores →</button></div></section></div>`}
function services(){return `${head('services')}<div class="workspace"><form id="serviceform" class="panel"><h3>Adicionar serviço</h3><label for="sname">Serviço</label><input id="sname" name="name" required maxlength="100" placeholder="Ex.: Instalação de equipamento"><label for="sperson">Responsável</label><input id="sperson" name="person" required maxlength="60" placeholder="Nome do responsável"><button class="full">Abrir serviço</button><p class="hint">Experimente avançar as etapas na lista ao lado.</p></form><section class="panel soft"><h3>Fluxo de trabalho</h3>${state.services.map((s,i)=>`<div class="row"><div><strong>${esc(s.name)}</strong><small>${esc(s.person)} · ${stages[s.stage]}</small></div><button data-advance="${i}" ${s.stage===3?'disabled':''}>${s.stage===3?'✓ Concluído':'Avançar →'}</button></div>`).join('')}<div class="actions"><button class="textbtn" data-go="checks">Combinar com conferências →</button></div></section></div>`}
function checks(){const list=['Materiais conferidos','Equipamento em boas condições','Local organizado','Responsável identificado'];return `${head('checks')}<div class="workspace"><section class="panel"><h3>Conferência de entrega</h3><p class="hint">Marque os itens que já foram verificados.</p>${list.map((s,i)=>`<label class="row"><input class="check" type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}>${s}</label>`).join('')}<label for="notes">Observações</label><textarea id="notes" placeholder="Ex.: Material danificado durante o transporte">${esc(state.notes||'')}</textarea><button id="checksave" class="full">Gerar resultado da inspeção</button></section><section class="panel soft"><h3>Resultado da conferência</h3><div class="metric">${state.checks.filter(Boolean).length} / 4</div><p class="hint">Itens conferidos</p><div class="result" id="checkresult">${esc(state.checkresult||'')}</div></section></div>`}
function schedule(){return `${head('schedule')}<div class="workspace"><form id="appointmentform" class="panel"><h3>Próximo compromisso</h3><label for="aname">Empresa ou contato</label><input id="aname" name="name" required maxlength="100" placeholder="Ex.: Cliente demonstração"><label for="adate">Data e hora</label><input id="adate" name="date" type="datetime-local" required><label for="atype">Tipo</label><select id="atype" name="type"><option>Retorno comercial</option><option>Visita</option><option>Entrega</option><option>Manutenção</option></select><button class="full">Agendar compromisso</button><p class="hint">Esta demonstração organiza os compromissos; não envia notificações.</p></form><section class="panel soft"><h3>Agenda da equipe</h3>${state.appointments.length?state.appointments.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(a=>`<div class="row"><div><strong>${esc(a.name)}</strong><small>${esc(a.type)} · ${new Date(a.date).toLocaleString('pt-BR')}</small></div><button data-done="${esc(a.id)}">${a.done?'✓ Realizado':'Concluir'}</button></div>`).join(''):'<p>Agende um compromisso para experimentar.</p>'}</section></div>`}
function reports(){const qty=state.records.reduce((a,b)=>a+Number(b.qty),0),done=state.services.filter(s=>s.stage===3).length;return `${head('reports')}<section class="panel"><h3>Uma visão do que está acontecendo</h3><p class="hint">Os números refletem os registros que você experimentou nas outras ferramentas.</p><div class="stats"><div><div class="metric">${state.records.length}</div><small>Registros realizados</small></div><div><div class="metric">${qty}</div><small>Unidades registradas</small></div><div><div class="metric">${done}/${state.services.length}</div><small>Serviços concluídos</small></div><div><div class="metric">${state.appointments.filter(a=>!a.done).length}</div><small>Compromissos pendentes</small></div></div><h3>Serviços por etapa</h3><div class="bars">${stages.map((s,i)=>{const n=state.services.filter(x=>x.stage===i).length;return `<div class="bar" style="height:${Math.max(5,n/Math.max(1,state.services.length)*120)}px" title="${s}: ${n}"><span>${s}<br>${n}</span></div>`}).join('')}</div><div class="actions"><button id="reportinsight">Interpretar esses dados · IA simulada</button></div><div class="result" id="insight" aria-live="polite"></div></section>`}
function ai(id){if(id==='extract')return `${head(id)}<div class="workspace"><section class="panel"><h3>Do texto para o registro</h3><p class="hint">Cole um texto com rótulos ou use um exemplo. Nesta simulação, a extração usa regras locais.</p><label for="extracttext">Conteúdo do documento</label><textarea id="extracttext" style="min-height:180px">Empresa: Oficina Horizonte\nPedido: 1042\nTotal: R$ 1.250,00\nEntrega: 15/10/2026</textarea><div class="actions"><button id="extractrun">Extrair informações</button><button id="extractexample" class="secondary">Outro exemplo</button></div></section><section class="panel soft"><h3>Campos para conferência</h3><div id="extractresult" class="result" aria-live="polite"></div><p class="hint">Confira os dados antes de usar. Fotos e OCR não estão conectados nesta versão.</p></section></div>`;if(id==='assistant')return `${head(id)}<div class="workspace"><section class="panel"><h3>Escolha um contexto</h3><label for="context">Cenário de atendimento</label><select id="context"><option>Manutenção de equipamentos</option><option>Distribuidora de materiais</option><option>Prestação de serviços</option><option>Consultoria empresarial</option></select><p class="hint">Experimente pedir preços, prazos ou ajuda com um problema.</p><div class="actions"><button class="secondary" data-prompt="Quero um orçamento para um serviço">Orçamento</button><button class="secondary" data-prompt="Meu pedido está atrasado">Problema</button><button class="secondary" data-prompt="Qual é o prazo de entrega?">Prazo</button></div></section><section class="panel soft"><h3>Conversa de demonstração</h3><div id="chat" aria-live="polite">${state.chat.map(m=>`<div class="message ${m.role}">${esc(m.text)}</div>`).join('')}</div><form id="chatform"><label for="chattext">Sua mensagem</label><input id="chattext" name="text" required maxlength="500" placeholder="Escreva um pedido"><button class="full">Enviar para o simulador →</button></form></section></div>`;return `${head(id)}<div class="workspace"><section class="panel"><h3>Comece por uma dificuldade real</h3><label for="sector">Segmento</label><select id="sector"><option>Serviços</option><option>Comércio</option><option>Indústria</option><option>Logística</option></select><label for="problem">O que você precisa resolver?</label><textarea id="problem" placeholder="Ex.: O estoque é controlado em papel e faltam materiais para executar os serviços."></textarea><div class="actions"><button id="diagnoserun">Explorar uma solução</button><button id="problemexample" class="secondary">Usar um exemplo</button></div></section><section class="panel soft"><h3>Possibilidades para sua empresa</h3><div id="diagnosisresult" class="result" aria-live="polite"></div><button id="addsuggestions" class="full" hidden>Adicionar ferramentas sugeridas</button></section></div>`}
function solution(custom=false){return `<div class="demohead"><div><span class="eyebrow">FEITA PARA SUA OPERAÇÃO</span><h1>${custom?'Criar ferramenta personalizada':'Minha solução'}</h1><p>${custom?'Sua ideia pode ser o começo da próxima ferramenta.':'As ferramentas que você escolheu, conectadas à sua necessidade.'}</p></div></div><div class="workspace"><section class="panel soft"><h3>${state.selected.length} ferramentas selecionadas</h3>${state.selected.length?state.selected.map(id=>{const t=tools.find(x=>x[0]===id);return t?`<div class="selectionrow"><span>${t[1]} ${t[2]}</span><button data-toggle="${id}">Remover</button></div>`:''}).join(''):'<p>Você pode descrever sua necessidade mesmo sem selecionar ferramentas.</p>'}<p class="hint">Cada ferramenta pode funcionar sozinha ou ser integrada às demais.</p><button class="textbtn" data-go="inicio">← Continuar explorando</button></section><form id="requestform" class="panel"><h3>Conte o que sua empresa precisa</h3><label for="qname">Seu nome</label><input id="qname" name="name" required maxlength="100"><label for="qcompany">Empresa</label><input id="qcompany" name="company" required maxlength="100"><label for="qrole">Cargo ou função</label><input id="qrole" name="role" required maxlength="100"><label for="qdescription">Descrição da necessidade</label><textarea id="qdescription" name="description" required maxlength="2000" placeholder="Como é feito hoje e o que você deseja melhorar?"></textarea><button class="full">Preparar solicitação para WhatsApp →</button><p class="hint">Revise a mensagem antes de compartilhar. Nada é enviado automaticamente.</p><div id="requestresult"></div></form></div>`}
let suggestions=[];async function simulate(button,result,fn){button.disabled=true;const old=button.textContent;button.textContent='Analisando o cenário…';result.textContent='Organizando as informações…';await new Promise(r=>setTimeout(r,550+Math.random()*650));try{result.textContent=fn()}finally{button.disabled=false;button.textContent=old}}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>toggle(b.dataset.toggle));if($('#search'))$('#search').oninput=e=>{$('#catalog').innerHTML=cards(tools.filter(t=>HorizonEngine.normalize(t.join(' ')).includes(HorizonEngine.normalize(e.target.value))));bindCards()};if($('#recordform'))$('#recordform').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.records.push({name:d.get('name').trim(),qty:Number(d.get('qty')),person:d.get('person').trim()});save();render();toast('Registro salvo. Planilha atualizada.')};if($('#csv'))$('#csv').onclick=()=>{const cell=s=>'"'+String(s).replace(/"/g,'""').replace(/^[=+@-]/,"'$&")+'"';download('horizon-registros.csv','\ufeffAtividade;Quantidade;Responsável\n'+state.records.map(r=>[r.name,r.qty,r.person].map(cell).join(';')).join('\n'),'text/csv;charset=utf-8')};if($('#serviceform'))$('#serviceform').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.services.push({name:d.get('name').trim(),person:d.get('person').trim(),stage:0});save();render();toast('Serviço aberto')};document.querySelectorAll('[data-advance]').forEach(b=>b.onclick=()=>{state.services[+b.dataset.advance].stage++;save();render()});document.querySelectorAll('[data-check]').forEach(b=>b.onchange=()=>{state.notes=$('#notes').value;state.checks[+b.dataset.check]=b.checked;state.checkresult='';save();render()});if($('#checksave'))$('#checksave').onclick=()=>{state.notes=$('#notes').value;const n=state.checks.filter(Boolean).length;state.checkresult=`${n===4?'Conferência concluída.':'Conferência com pendências.'}\n${n} itens verificados; ${4-n} itens aguardando conferência.\n${state.notes?'Observação: '+state.notes:'Sem observações registradas.'}`;save();render()};if($('#appointmentform'))$('#appointmentform').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);state.appointments.push({id:String(Date.now()),name:d.get('name').trim(),date:d.get('date'),type:d.get('type'),done:false});save();render();toast('Compromisso agendado')};document.querySelectorAll('[data-done]').forEach(b=>b.onclick=()=>{const a=state.appointments.find(a=>a.id===b.dataset.done);a.done=!a.done;save();render()});if($('#reportinsight'))$('#reportinsight').onclick=e=>simulate(e.target,$('#insight'),()=>{const done=state.services.filter(s=>s.stage===3).length;return `Leitura dos dados desta demonstração:\n\n${state.services.length-done} serviços ainda estão em andamento. ${done?done+' já foram concluídos.':'Ainda não há serviços concluídos.'}\n${state.records.length} registros acumulam ${state.records.reduce((a,b)=>a+Number(b.qty),0)} unidades.\n\nPróximo passo sugerido: conferir os serviços em execução e os responsáveis. Quantidade de registros não mede produtividade sozinha; o período e o tipo de atividade também precisam ser considerados.`});if($('#extractrun'))$('#extractrun').onclick=e=>simulate(e.target,$('#extractresult'),()=>Object.entries(HorizonEngine.extract($('#extracttext').value)).map(([k,v])=>`${{empresa:'Empresa',documento:'Documento',valor:'Valor',prazo:'Prazo'}[k]}: ${v}`).join('\n'));if($('#extractexample'))$('#extractexample').onclick=()=>{$('#extracttext').value=['Fornecedor: Distribuidora Azul\nNota: 8921\nValor: R$ 780,50\nData: 18/10/2026','Cliente: Empresa Exemplo\nPedido: 553\nEntrega: A confirmar','Empresa: Oficina Horizonte\nNota: 1205\nTotal: R$ 2.490,00\nPrazo: 22/10/2026'][state.turn++%3]};if($('#diagnoserun'))$('#diagnoserun').onclick=e=>simulate(e.target,$('#diagnosisresult'),()=>{const r=HorizonEngine.diagnose($('#problem').value,$('#sector').value,state.turn++);suggestions=r.tools.map(name=>tools.find(t=>t[2]===name)?.[0]).filter(Boolean);$('#addsuggestions').hidden=!suggestions.length;return r.body});if($('#problemexample'))$('#problemexample').onclick=()=>{$('#problem').value=['O estoque é anotado em papel e faltam peças para os serviços.','Perdemos retornos de clientes porque as visitas ficam em conversas separadas.','A equipe demora nas etapas de manutenção e ninguém sabe o prazo de entrega.','Recebemos pedidos e notas por texto e digitamos tudo na planilha.'][state.turn++%4]};if($('#addsuggestions'))$('#addsuggestions').onclick=()=>{state.selected=[...new Set([...state.selected,...suggestions])];save();toast('Ferramentas sugeridas adicionadas à sua solução')};document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{$('#chattext').value=b.dataset.prompt;$('#chattext').focus()});if($('#chatform'))$('#chatform').onsubmit=async e=>{e.preventDefault();const text=$('#chattext').value.trim();if(!text)return;const context=$('#context').value;state.chat.push({role:'user',text});if(state.chat.length>12)state.chat=state.chat.slice(-12);$('#chat').innerHTML=state.chat.map(m=>`<div class="message ${m.role}">${esc(m.text)}</div>`).join('');const button=e.target.querySelector('button');button.disabled=true;await new Promise(r=>setTimeout(r,650));state.chat.push({role:'assistant',text:HorizonEngine.reply(text,context,state.turn++)});save();$('#chat').innerHTML=state.chat.map(m=>`<div class="message ${m.role}">${esc(m.text)}</div>`).join('');$('#chattext').value='';button.disabled=false};if($('#requestform'))$('#requestform').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);const text=`Olá, Horizon! Quero uma solução personalizada.\n\nNome: ${d.get('name').trim()}\nEmpresa: ${d.get('company').trim()}\nCargo/função: ${d.get('role').trim()}\nFerramentas: ${state.selected.map(id=>tools.find(t=>t[0]===id)?.[2]).filter(Boolean).join(', ')||'A definir'}\n\nNecessidade: ${d.get('description').trim()}`;$('#requestresult').innerHTML=`<label for="prepared">Revise sua solicitação</label><textarea id="prepared" style="min-height:210px">${esc(text)}</textarea><div class="actions"><button type="button" id="copy">Copiar mensagem</button><button type="button" id="whatsapp" class="secondary">Abrir WhatsApp</button></div><p class="hint">O número da Horizon ainda não foi configurado. No WhatsApp, escolha o contato destinatário.</p>`;$('#copy').onclick=async()=>{try{await navigator.clipboard.writeText($('#prepared').value);toast('Mensagem copiada')}catch{$('#prepared').select();toast('Selecione e copie a mensagem acima')}};$('#whatsapp').onclick=()=>window.open('https://api.whatsapp.com/send?text='+encodeURIComponent($('#prepared').value),'_blank','noopener,noreferrer')};}
function bindCards(){document.querySelectorAll('#catalog [data-go]').forEach(b=>b.onclick=()=>location.hash=b.dataset.go);document.querySelectorAll('#catalog [data-toggle]').forEach(b=>b.onclick=()=>toggle(b.dataset.toggle))}function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function render(){const route=location.hash.slice(1)||'inicio';$('#nav').innerHTML=`<button data-go="inicio" class="${route==='inicio'?'active':''}">⌂ <span>Visão geral</span></button>`+tools.map(t=>`<button data-go="${t[0]}" class="${route===t[0]?'active':''}">${t[1]} <span>${t[2]}</span></button>`).join('')+`<button data-go="personalizada" class="${route==='personalizada'?'active':''}">＋ <span>Criar ferramenta personalizada</span></button>`;const views={inicio:home,records,services,checks,schedule,reports,assistant:()=>ai('assistant'),extract:()=>ai('extract'),diagnosis:()=>ai('diagnosis'),solucao:()=>solution(),personalizada:()=>solution(true)};$('#main').innerHTML=(views[route]||home)();$('#breadcrumb').textContent=tools.find(t=>t[0]===route)?.[2]||({solucao:'Minha solução',personalizada:'Sua ferramenta'}[route])||'Visão geral';$('#count').textContent=state.selected.length;bind();closeMenu()};window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});render();
